import{_ as a}from"./chunks/calendar-month-1440.Ddt_hq6k.js";import{_ as t,c as n,o as r,ag as i}from"./chunks/framework.CazwtNDk.js";const f=JSON.parse('{"title":"Calendar 🗓️","description":"","frontmatter":{"layout":"doc","prev":false,"next":false},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788803607000}'),o={name:"index.md"};function s(d,e,l,c,h,u){return r(),n("div",null,e[0]||(e[0]=[i('<h1 id="calendar-🗓️" tabindex="-1">Calendar 🗓️ <a class="header-anchor" href="#calendar-🗓️" aria-label="Permalink to &quot;Calendar 🗓️&quot;">​</a></h1><p>Calendar is a self-hosted calendar and holiday service with an embedded management UI, a Go API, and iCalendar (ICS) import, export, and subscriptions. Use it to plan team events, maintain recurring holidays, and build calendars for different entities.</p><p><img src="'+a+'" alt="Calendar month view with group filters and a selected-day agenda"></p><h2 id="what-you-can-do" tabindex="-1">What You Can Do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What You Can Do&quot;">​</a></h2><ul><li>Browse month, week, day, and year views, with a selected-day agenda and mobile layout.</li><li>Create all-day and timed events with explicit time zones, recurring schedules, and special holiday rules.</li><li>Group events and assign whole groups or individual events to named entities.</li><li>Import ICS files or share enabled events through scoped downloads and subscription URLs.</li><li>Run a single Go binary with PostgreSQL; the UI needs no separate frontend server.</li></ul><h2 id="start-using-calendar" tabindex="-1">Start Using Calendar <a class="header-anchor" href="#start-using-calendar" aria-label="Permalink to &quot;Start Using Calendar&quot;">​</a></h2><p>Follow the <a href="/calendar/quickstart">Quickstart</a> to configure PostgreSQL and run the service. Then open the <a href="/calendar/ui-guide">User Guide</a> for event editing, filters, assignments, and calendar sharing. Developers can find frontend commands and checks in the <a href="https://github.com/rakunlabs/calendar/blob/main/_ui/README.md" target="_blank" rel="noreferrer">UI README</a>.</p><div class="warning custom-block"><p class="custom-block-title">Protect Your Deployment</p><p>Calendar does not provide authentication for the UI or API. Put access controls in front of both before exposing the service. The optional <code>X-User</code> audit label, entity filters, and subscription URLs are not authorization mechanisms.</p></div><hr><p>Report bugs and request improvements on <a href="https://github.com/rakunlabs/calendar/issues" target="_blank" rel="noreferrer">GitHub</a>.</p>',10)]))}const g=t(o,[["render",s]]);export{f as __pageData,g as default};
